//! Port of `tests/test2.cpp`.
//!
//! Builds either as part of the Cargo package (`cargo build --release`, binary
//! `test2`) or standalone with `rustc test2.rs`, which is why the library
//! modules are pulled in with `#[path]` instead of `use indicators::…`.

#[path = "src/indicators/mod.rs"]
#[allow(dead_code)]
mod indicators;

use crate::indicators::{Percentage, ProgressBar};

fn main() {
    // `int main(int argc, char* argv[])` accepts arguments but never reads
    // them, so the output is the same for any command line.
    let _args: Vec<String> = std::env::args().collect();

    let mut bar = ProgressBar::new();
    bar.set_progress(75);
    bar.set_total(100);
    bar.set_width(30);
    println!("{}", bar.str());

    let pct = Percentage::new(0.75);
    println!("{}", pct.str());
}
